from lib import *
import math, itertools
from collections import Counter
def iv(s): return list(map(int, s.split()))
def arrs(s): a = iv(s); return a[1:1 + a[0]]
def J(a): return ' '.join(map(str, a))
def W(s): return s.strip().split('\n')
subject('cs11', 'Computer Science - Class 11 (Python)', 'python', 'cs11', 'Python practice for the Class 11 syllabus. Every topic is a no-timer session.')
N1 = num(1, 100); N2 = two(1, 50); A = ar(-20, 20, 1, 10); S = st(1, 12, 'abcde'); WD = wds(1, 6)

topic('basics', 'Python Basics, Input and Operators', 'Variables, input, output, arithmetic and type conversion')
Q('Easy', 'Hello Name', 'Read a name and print "Hello, <name>!". | Input: one line, the name. | Output: the greeting.', lambda s: 'Hello, %s!' % s.strip(), [L('Asha')], WD)
Q('Easy', 'Add Two Numbers', 'Print the sum of two integers. | Input: two integers on two lines. | Output: their sum.', lambda s: sum(iv(s)), [L(3, 4)], two(-100, 100))
Q('Easy', 'Area of Rectangle', 'Print the area of a rectangle. | Input: length, then breadth. | Output: the area.', lambda s: iv(s)[0] * iv(s)[1], [L(5, 3)], N2)
Q('Easy', 'Simple Interest', 'Print simple interest (P*R*T/100) with two decimals. | Input: P, R, T on three lines. | Output: the interest.', lambda s: '%.2f' % (iv(s)[0] * iv(s)[1] * iv(s)[2] / 100), [L(1000, 5, 2)], lambda r: L(r.randint(100, 5000), r.randint(1, 12), r.randint(1, 10)))
Q('Easy', 'Celsius to Fahrenheit', 'Convert Celsius to Fahrenheit (F = C*9/5 + 32) and print with one decimal. | Input: C. | Output: F.', lambda s: '%.1f' % (int(s) * 9 / 5 + 32), [L(100)], num(-40, 120))
