Q('Medium', 'Sum of Digits of Two-Digit', 'Print the sum of the digits of a two-digit number. | Input: N (10 to 99). | Output: the digit sum.', lambda s: sum(map(int, s.strip())), [L(47)], num(10, 99))
Q('Medium', 'Seconds to HH:MM:SS', 'Convert a number of seconds to H:M:S (no padding). | Input: S. | Output: H:M:S.', lambda s: '%d:%d:%d' % (int(s) // 3600, int(s) % 3600 // 60, int(s) % 60), [L(3725)], num(0, 100000))
Q('Medium', 'Average of Three', 'Print the average of three numbers with two decimals. | Input: three integers on three lines. | Output: the average.', lambda s: '%.2f' % (sum(iv(s)) / 3), [L(70, 80, 90)], lambda r: L(r.randint(0, 100), r.randint(0, 100), r.randint(0, 100)))
Q('Medium', 'Compound Value', 'Print P*(1+R/100)^T rounded to two decimals. | Input: P, R, T on three lines. | Output: the amount.', lambda s: '%.2f' % (iv(s)[0] * (1 + iv(s)[1] / 100) ** iv(s)[2]), [L(1000, 10, 2)], lambda r: L(r.randint(100, 3000), r.randint(1, 15), r.randint(1, 6)))
