topic('cond', 'Conditional Statements', 'if, elif and else decisions')
Q('Easy', 'Even or Odd', 'Print EVEN or ODD. | Input: N. | Output: EVEN or ODD.', lambda s: 'EVEN' if int(s) % 2 == 0 else 'ODD', [L(7)], num(0, 200))
Q('Easy', 'Positive Negative Zero', 'Print POSITIVE, NEGATIVE or ZERO. | Input: N. | Output: the word.', lambda s: 'POSITIVE' if int(s) > 0 else 'NEGATIVE' if int(s) < 0 else 'ZERO', [L(-4)], num(-5, 5))
