Q('Easy', 'Largest of Three', 'Print the largest of three numbers. | Input: three integers on three lines. | Output: the largest.', lambda s: max(iv(s)), [L(4, 9, 2)], lambda r: L(r.randint(-20, 20), r.randint(-20, 20), r.randint(-20, 20)))
Q('Easy', 'Divisible by 5 and 11', 'Print YES if N is divisible by both 5 and 11, else NO. | Input: N. | Output: YES or NO.', lambda s: 'YES' if int(s) % 55 == 0 else 'NO', [L(110)], lambda r: L(r.choice([55 * r.randint(0, 20), r.randint(1, 1000)])))
Q('Easy', 'Voting Eligibility', 'Print ELIGIBLE if age is 18 or more, else NOT ELIGIBLE. | Input: age. | Output: the result.', lambda s: 'ELIGIBLE' if int(s) >= 18 else 'NOT ELIGIBLE', [L(17)], num(1, 90))
Q('Easy', 'Pass or Fail', 'Marks 33 or more means PASS, else FAIL. | Input: marks. | Output: PASS or FAIL.', lambda s: 'PASS' if int(s) >= 33 else 'FAIL', [L(40)], num(0, 100))
Q('Medium', 'Grade From Marks', 'A for 90+, B for 75-89, C for 60-74, D for 33-59, else F. | Input: marks. | Output: the grade.', lambda s: (lambda m: 'A' if m >= 90 else 'B' if m >= 75 else 'C' if m >= 60 else 'D' if m >= 33 else 'F')(int(s)), [L(82)], num(0, 100))
Q('Medium', 'Leap Year', 'Print YES if the year is a leap year, else NO. | Input: year. | Output: YES or NO.', lambda s: (lambda y: 'YES' if y % 4 == 0 and (y % 100 or y % 400 == 0) else 'NO')(int(s)), [L(2000), L(1900)], num(1, 3000))
Q('Medium', 'Triangle Type', 'Given three sides print EQUILATERAL, ISOSCELES, SCALENE or NOT A TRIANGLE. | Input: three sides on three lines. | Output: the type.', lambda s: (lambda a, b, c: 'NOT A TRIANGLE' if a + b <= c or a + c <= b or b + c <= a else 'EQUILATERAL' if a == b == c else 'ISOSCELES' if a == b or b == c or a == c else 'SCALENE')(*iv(s)), [L(3, 4, 5)], lambda r: L(r.randint(1, 8), r.randint(1, 8), r.randint(1, 8)))
Q('Medium', 'Quadrant', 'Given a point (x, y) print the quadrant 1-4, or AXIS if it lies on an axis. | Input: x then y. | Output: the quadrant.', lambda s: (lambda x, y: 'AXIS' if x == 0 or y == 0 else 1 if x > 0 and y > 0 else 2 if x < 0 < y else 3 if x < 0 and y < 0 else 4)(*iv(s)), [L(3, -2)], two(-4, 4))
Q('Medium', 'Electricity Bill', 'First 100 units cost 5 each, the next 100 cost 7 each and anything beyond costs 10 each. Print the bill. | Input: units. | Output: the bill.', lambda s: (lambda u: min(u, 100) * 5 + max(0, min(u, 200) - 100) * 7 + max(0, u - 200) * 10)(int(s)), [L(250)], num(0, 400))
Q('Medium', 'Day Name', 'Print the day name for 1=Monday ... 7=Sunday, else INVALID. | Input: N. | Output: the day.', lambda s: (['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] + ['INVALID'] * 0)[int(s) - 1] if 1 <= int(s) <= 7 else 'INVALID', [L(3)], num(0, 9))
Q('Medium', 'Character Type', 'Print VOWEL, CONSONANT, DIGIT or OTHER for one character. | Input: one character. | Output: the type.', lambda s: (lambda c: 'VOWEL' if c.lower() in 'aeiou' else 'CONSONANT' if c.isalpha() else 'DIGIT' if c.isdigit() else 'OTHER')(s.strip()), [L('e')], lambda r: L(r.choice('aEbZ5#xU9')))
Q('Hard', 'Valid Date', 'Print YES if D M Y is a real date (consider leap years), else NO. | Input: day, month, year on three lines. | Output: YES or NO.', lambda s: (lambda d, m, y: 'YES' if 1 <= m <= 12 and 1 <= d <= [31, 29 if y % 4 == 0 and (y % 100 or y % 400 == 0) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1] else 'NO')(*iv(s)), [L(29, 2, 2000)], lambda r: L(r.randint(1, 32), r.randint(1, 13), r.choice([1900, 2000, 2023, 2024])))
Q('Hard', 'Median of Three', 'Print the middle value of three numbers. | Input: three integers on three lines. | Output: the median.', lambda s: sorted(iv(s))[1], [L(9, 2, 5)], lambda r: L(r.randint(-9, 9), r.randint(-9, 9), r.randint(-9, 9)))
Q('Hard', 'Roots of Quadratic', 'For ax^2+bx+c print REAL if the roots are real and distinct, EQUAL if repeated, else COMPLEX. | Input: a, b, c on three lines (a != 0). | Output: the word.', lambda s: (lambda a, b, c: 'REAL' if b * b - 4 * a * c > 0 else 'EQUAL' if b * b - 4 * a * c == 0 else 'COMPLEX')(*iv(s)), [L(1, -2, 1)], lambda r: L(r.choice([-3, -1, 1, 2]), r.randint(-6, 6), r.randint(-6, 6)))
Q('Hard', 'Postage', 'Letters up to 20 g cost 5, up to 50 g cost 9, up to 100 g cost 15, heavier ones cost 15 plus 4 for every extra 50 g or part of it. Print the cost. | Input: weight in grams. | Output: the cost.', lambda s: (lambda w: 5 if w <= 20 else 9 if w <= 50 else 15 if w <= 100 else 15 + 4 * math.ceil((w - 100) / 50))(int(s)), [L(130)], num(1, 400))
Q('Hard', 'Compare Dates', 'Two dates are given as D M Y on one line each. Print EARLIER, LATER or SAME for the first date compared with the second. | Input: two lines. | Output: the word.', lambda s: (lambda a, b: 'SAME' if a == b else 'EARLIER' if a < b else 'LATER')(*[tuple(reversed(list(map(int, l.split())))) for l in W(s)]), [L('1 2 2020', '5 1 2020')], lambda r: L(*['%d %d %d' % (r.randint(1, 28), r.randint(1, 12), r.choice([2020, 2021])) for _ in range(2)]))
Q('Hard', 'Rock Paper Scissors', 'Two players give r, p or s. Print 1 if player 1 wins, 2 if player 2 wins, or DRAW. | Input: two letters on two lines. | Output: the result.', lambda s: (lambda a, b: 'DRAW' if a == b else '1' if (a, b) in [('r', 's'), ('s', 'p'), ('p', 'r')] else '2')(*W(s)), [L('r', 's')], lambda r: L(r.choice('rps'), r.choice('rps')))

topic('loops', 'Loops', 'for and while loops, patterns and counting')
Q('Easy', 'Print 1 to N', 'Print the numbers from 1 to N separated by spaces. | Input: N. | Output: the sequence.', lambda s: J(range(1, int(s) + 1)), [L(5)], num(1, 20))
Q('Easy', 'Sum 1 to N', 'Print 1+2+...+N. | Input: N. | Output: the sum.', lambda s: int(s) * (int(s) + 1) // 2, [L(10)], num(1, 1000))
Q('Easy', 'Table of N', 'Print N x 1 up to N x 10, one per line as "N x i = result". | Input: N. | Output: ten lines.', lambda s: '\n'.join('%d x %d = %d' % (int(s), i, int(s) * i) for i in range(1, 11)), [L(3)], num(1, 30))
