Q('Medium', 'Fibonacci Series', 'Print the first N Fibonacci numbers (0 1 1 2 ...). | Input: N. | Output: the series.', lambda s: J((lambda n: [0, 1][:n] if n < 3 else (lambda a: [a.append(a[-1] + a[-2]) for _ in range(n - 2)] and a)([0, 1]))(int(s))), [L(7)], num(1, 20))
Q('Medium', 'Reverse a Number', 'Reverse the digits of N using a loop. | Input: N. | Output: the reversed number.', lambda s: int(s.strip()[::-1]), [L(1234)], num(1, 10**8))
Q('Medium', 'Is Prime', 'Print YES if N is prime, else NO. | Input: N. | Output: YES or NO.', lambda s: 'YES' if (lambda n: n > 1 and all(n % d for d in range(2, int(n ** .5) + 1)))(int(s)) else 'NO', [L(29)], num(1, 2000))
Q('Medium', 'Number Pyramid', 'Print N rows; row i has the numbers 1..i separated by spaces. | Input: N. | Output: N lines.', lambda s: '\n'.join(J(range(1, i + 1)) for i in range(1, int(s) + 1)), [L(4)], num(1, 8))
Q('Medium', 'Armstrong Check', 'Print YES if N equals the sum of the cubes of its digits (three-digit Armstrong), else NO. | Input: N. | Output: YES or NO.', lambda s: 'YES' if sum(int(c) ** 3 for c in s.strip()) == int(s) else 'NO', [L(153)], lambda r: L(r.choice([153, 370, 371, 407, r.randint(100, 999)])))
Q('Medium', 'GCD by Loop', 'Print the GCD of two numbers using the Euclid loop. | Input: A then B. | Output: the GCD.', lambda s: math.gcd(*iv(s)), [L(12, 18)], two(1, 500))
Q('Medium', 'Collatz Steps', 'Repeat: if N is even divide by 2, else N = 3N+1, until N is 1. Print the number of steps. | Input: N. | Output: the steps.', lambda s: (lambda n: (lambda f: f(f, n, 0))(lambda f, x, c: c if x == 1 else f(f, x // 2 if x % 2 == 0 else 3 * x + 1, c + 1)))(int(s)), [L(6)], num(1, 200))
Q('Hard', 'Hollow Square', 'Print an N x N hollow square of stars (N>=2). | Input: N. | Output: N lines.', lambda s: '\n'.join('*' * int(s) if i in (0, int(s) - 1) else '*' + ' ' * (int(s) - 2) + '*' for i in range(int(s))), [L(4)], num(2, 8))
Q('Hard', 'Sum of Series', 'Print 1 + 1/2 + 1/3 + ... + 1/N with three decimals. | Input: N. | Output: the sum.', lambda s: '%.3f' % sum(1 / k for k in range(1, int(s) + 1)), [L(4)], num(1, 50))
Q('Hard', 'Perfect Numbers', 'Print all perfect numbers up to N separated by spaces, or - if none. | Input: N. | Output: the numbers.', lambda s: J(n for n in range(2, int(s) + 1) if sum(d for d in range(1, n) if n % d == 0) == n) or '-', [L(30)], num(1, 600))
Q('Hard', 'Diamond of Stars', 'Print a diamond of stars with N rows in the top half (widest row has 2N-1 stars). | Input: N. | Output: 2N-1 lines.', lambda s: '\n'.join(' ' * (int(s) - k) + '*' * (2 * k - 1) for k in list(range(1, int(s) + 1)) + list(range(int(s) - 1, 0, -1))), [L(3)], num(1, 6))
Q('Hard', 'Count Primes Up To N', 'Print how many primes are at most N. | Input: N. | Output: the count.', lambda s: sum(1 for n in range(2, int(s) + 1) if all(n % d for d in range(2, int(n ** .5) + 1))), [L(30)], num(1, 1500))
Q('Hard', 'Digit Frequency', 'Print how many times each digit 0-9 appears in N, as ten numbers. | Input: N. | Output: ten counts.', lambda s: J(s.strip().count(str(d)) for d in range(10)), [L(112233)], lambda r: L(r.randint(1, 10**9)))

topic('strings', 'Strings', 'Indexing, slicing, methods and text processing')
Q('Easy', 'String Length', 'Print the number of characters in the line. | Input: a line. | Output: the length.', lambda s: len(s.rstrip('\n')), [L('hello world')], WD)
Q('Easy', 'Uppercase', 'Print the line in uppercase. | Input: a line. | Output: the uppercase line.', lambda s: s.strip().upper(), [L('Study Hard')], WD)
Q('Easy', 'Reverse a String', 'Print the line reversed. | Input: a line. | Output: reversed.', lambda s: s.strip()[::-1], [L('python')], S)
Q('Easy', 'Count a Letter', 'Count how many times the letter appears in the word (case sensitive). | Input: the word, then the letter. | Output: the count.', lambda s: W(s)[0].count(W(s)[1]), [L('banana', 'a')], lambda r: L(''.join(r.choice('abc') for _ in range(r.randint(1, 10))), r.choice('abc')))
