Q('Medium', 'Count Vowels and Consonants', 'Print vowels and consonants counts (letters only, case-insensitive), separated by a space. | Input: a line. | Output: V C.', lambda s: (lambda t: '%d %d' % (sum(c in 'aeiou' for c in t), sum(c.isalpha() and c not in 'aeiou' for c in t)))(s.lower()), [L('Hello World')], WD)
Q('Medium', 'Title Case', 'Print each word with only its first letter capitalised. | Input: a line. | Output: the new line.', lambda s: ' '.join(w.capitalize() for w in s.split()), [L('hELLO wORLD')], wds(1, 5, 'aBcD'))
Q('Medium', 'Replace Spaces', 'Replace every space with an underscore. | Input: a line. | Output: the new line.', lambda s: s.rstrip('\n').replace(' ', '_'), [L('a b c')], WD)
Q('Medium', 'Remove Vowels', 'Print the word without vowels (a e i o u, both cases). | Input: a line. | Output: the new line.', lambda s: ''.join(c for c in s.strip() if c not in 'aeiouAEIOU'), [L('Education')], WD)
Q('Medium', 'Longest Word', 'Print the longest word (the first one on a tie). | Input: a line. | Output: the word.', lambda s: max(s.split(), key=len), [L('learn python daily')], wds(1, 6, 'abc', (1, 7)))
Q('Medium', 'Caesar Shift', 'Shift every lowercase letter forward by K (wrap around z to a); keep other characters. | Input: the text, then K. | Output: the shifted text.', lambda s: ''.join(chr((ord(c) - 97 + int(W(s)[1])) % 26 + 97) if c.islower() else c for c in W(s)[0]), [L('abc xyz', 3)], lambda r: L(''.join(r.choice('abc xyz') for _ in range(r.randint(1, 10))), r.randint(0, 30)))
Q('Medium', 'Swap Case', 'Swap the case of every letter. | Input: a line. | Output: the new line.', lambda s: s.rstrip('\n').swapcase(), [L('Hello')], st(1, 9, 'aBcD'))
Q('Hard', 'Anagram Check', 'Print YES if the two words are anagrams (ignore case), else NO. | Input: two lines. | Output: YES or NO.', lambda s: 'YES' if sorted(W(s)[0].lower()) == sorted(W(s)[1].lower()) else 'NO', [L('Listen', 'Silent')], lambda r: L(*[''.join(r.choice('abc') for _ in range(r.randint(1, 4))) for _ in range(2)]))
Q('Hard', 'Compress Runs', 'Compress runs of the same character as char+count (aaabb becomes a3b2). | Input: a word. | Output: the compressed text.', lambda s: ''.join(k + str(len(list(g))) for k, g in itertools.groupby(s.strip())), [L('aaabbc')], st(1, 12, 'ab'))
Q('Hard', 'Most Frequent Letter', 'Print the most frequent letter (smallest on a tie). | Input: a lowercase word. | Output: the letter.', lambda s: min(Counter(s.strip()).items(), key=lambda x: (-x[1], x[0]))[0], [L('mississippi')], st(1, 12, 'abcd'))
Q('Hard', 'Word Frequency', 'Print each distinct word with its count, in alphabetical order, one per line as "word count". | Input: a line of lowercase words. | Output: the lines.', lambda s: '\n'.join('%s %d' % kv for kv in sorted(Counter(s.split()).items())), [L('a b a c b a')], wds(1, 8, 'ab', (1, 2)))
Q('Hard', 'Validate Password', 'A password is VALID if it has at least 8 characters and contains an uppercase letter, a lowercase letter and a digit; else INVALID. | Input: the password. | Output: VALID or INVALID.', lambda s: (lambda p: 'VALID' if len(p) >= 8 and any(c.isupper() for c in p) and any(c.islower() for c in p) and any(c.isdigit() for c in p) else 'INVALID')(s.strip()), [L('Study2025ok')], lambda r: L(''.join(r.choice('aA1x') for _ in range(r.randint(1, 10)))))
Q('Hard', 'Binary to Decimal', 'Convert a binary string to decimal without using int(x, 2). | Input: a binary string. | Output: the number.', lambda s: int(s.strip(), 2), [L('1011')], lambda r: L(''.join(r.choice('01') for _ in range(r.randint(1, 12)))))
Q('Hard', 'Longest Common Prefix of Two', 'Print the longest common prefix of two words, or - if none. | Input: two lines. | Output: the prefix.', lambda s: (lambda a, b: next((a[:i] for i in range(min(len(a), len(b)), 0, -1) if a[:i] == b[:i]), '-'))(*W(s)), [L('flower', 'flow')], lambda r: L(*[''.join(r.choice('ab') for _ in range(r.randint(1, 6))) for _ in range(2)]))
